    def find_corners(lines):
        corners = []
        for y, line in enumerate(lines):
            for x, char in enumerate(line):
                if char == '+':
                    corners.append((x, y))
        return corners

    def is_square(lines, top_left, bottom_right):
        x1, y1 = top_left
        x2, y2 = bottom_right
        width = x2 - x1 + 1
        height = y2 - y1 + 1
        if width != height:
            return False
        for y in range(y1, y2 + 1):
            if lines[y][x1] != '+' or lines[y][x2] != '+':
                return False
        for x in range(x1, x2 + 1):
            if lines[y1][x] != '+' or lines[y2][x] != '+':
                return False
        for y in range(y1 + 1, y2):
            for x in range(x1 + 1, x2):
                if lines[y][x] != '-':
                    return False
        return True

    corners = find_corners(lines)
    count = 0
    n = len(corners)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                for l in range(k + 1, n):
                    top_left = min(corners[i], corners[j], corners[k], corners[l], key=lambda c: (c[1], c[0]))
